package com.eventdrivencommerce.payment.infrastructure.persistence;
import com.eventdrivencommerce.payment.domain.*; import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import java.math.BigDecimal; import java.sql.Types; import java.time.Instant; import java.util.UUID;
@Entity @Table(name="payments") class PaymentJpaEntity {
 @Id UUID id;@Column(name="order_id",nullable=false,unique=true)UUID orderId;@Column(nullable=false,precision=19,scale=2)BigDecimal amount;@JdbcTypeCode(Types.CHAR)@Column(nullable=false,length=3,columnDefinition="char(3)")String currency;@Enumerated(EnumType.STRING)@Column(nullable=false,length=24)PaymentStatus status;@Column(name="provider_reference",length=120)String providerReference;@Column(name="failure_reason",length=64)String failureReason;@Column(name="refund_id")UUID refundId;@Column(name="refund_provider_reference",length=120)String refundProviderReference;@Column(name="created_at",nullable=false)Instant createdAt;@Column(name="updated_at",nullable=false)Instant updatedAt;@Version long version;
 protected PaymentJpaEntity(){} PaymentJpaEntity(Payment p){copy(p);}void copy(Payment p){id=p.id();orderId=p.orderId();amount=p.amount();currency=p.currency();status=p.status();providerReference=p.providerReference();failureReason=p.failureReason();refundId=p.refundId();refundProviderReference=p.refundProviderReference();createdAt=p.createdAt();updatedAt=p.updatedAt();}Payment domain(){return Payment.restore(id,orderId,amount,currency,status,providerReference,failureReason,refundId,refundProviderReference,createdAt,updatedAt);}
}
